function unlockAudio() {
  if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  audioCtx.resume().then(() => {
    btnAudio.hide();
    let silent = audioCtx.createOscillator();
    let g = audioCtx.createGain();
    g.gain.value = 0.00001; 
    silent.connect(g);
    g.connect(audioCtx.destination);
    silent.start();
  });
}

function createControl(id, txt, min, max, def, stp, x, y) {
  let l = createP(txt);
  l.style("color: white; font-family: sans-serif; font-size: 10px; margin: 0; position: absolute; z-index:100;");
  l.position(x, y);
  let s = createSlider(min, max, def, stp);
  s.position(x, y + 16);
  s.style('width', '160px');
  s.style('z-index', '101');
  s.elt.onmousedown = () => { isControlActive = true; if(audioCtx) audioCtx.resume(); };
  s.elt.onmouseup = () => { isControlActive = false; };
  sliders[id] = s;
}

function resetCamera() {
  cam.setPosition(0, 0, (height/2) / tan(PI/6));
  cam.lookAt(0, 0, 0);
  cam.upX = 0;
  cam.upY = 1;
  cam.upZ = 0;
}

function exportSettings() {
  let settings = {
    sound: checkboxSound.checked(),
    sliders: {},
    camState: {
      eyeX: cam.eyeX,
      eyeY: cam.eyeY,
      eyeZ: cam.eyeZ,
      centerX: cam.centerX,
      centerY: cam.centerY,
      centerZ: cam.centerZ,
      upX: cam.upX,
      upY: cam.upY,
      upZ: cam.upZ
    }
  };

  for (let id in sliders) {
    settings.sliders[id] = sliders[id].value();
  }

  saveJSON(settings, 'optics_3d_scene.json');
  console.log('Export réussi:', settings);
}

function loadPreset() {
  let presetName = presetSelect.value();
  if (presetName === '-- Choisir preset --') return;

  let preset = PRESETS[presetName];
  if (preset) {
    applySettings(preset);
    console.log('Preset chargé:', presetName);
  }
}

function applySettings(data) {
  // Restaurer les paramètres
  if (data.sound !== undefined) {
    checkboxSound.checked(data.sound);
  }

  if (data.sliders) {
    for (let id in data.sliders) {
      if (sliders[id]) {
        sliders[id].value(data.sliders[id]);
      }
    }
  }

  // Restaurer la caméra si disponible
  if (data.camState) {
    isControlActive = true;

    cam.eyeX = data.camState.eyeX;
    cam.eyeY = data.camState.eyeY;
    cam.eyeZ = data.camState.eyeZ;
    cam.centerX = data.camState.centerX;
    cam.centerY = data.camState.centerY;
    cam.centerZ = data.camState.centerZ;
    cam.upX = data.camState.upX;
    cam.upY = data.camState.upY;
    cam.upZ = data.camState.upZ;

    cam.camera(
      data.camState.eyeX, data.camState.eyeY, data.camState.eyeZ,
      data.camState.centerX, data.camState.centerY, data.camState.centerZ,
      data.camState.upX, data.camState.upY, data.camState.upZ
    );

    setTimeout(() => { isControlActive = false; }, 100);
  }

  initRays();
}

function importSettings(file) {
  console.log('Type de fichier:', file.type);
  console.log('Données:', file.data);

  // Parser le JSON si c'est une chaîne
  let data = file.data;
  if (typeof data === 'string') {
    try {
      data = JSON.parse(data);
    } catch(e) {
      console.error('Erreur de parsing JSON:', e);
      return;
    }
  }

  console.log('Données parsées:', data);
  applySettings(data);
}

function initRays() {
  rays = [];
  let count = sliders.count.value();
  let gap = sliders.spacing.value();
  for (let i = 0; i < count; i++) {
    let angle = map(i, 0, count, 0, TWO_PI);
    rays.push({
      y: sin(angle) * gap, 
      z: cos(angle) * gap,
      history: [], 
      progress: random(1), 
      isInside: false
    });
  }
}

function draw() {
  background(10);

  // OrbitControl seulement si aucun contrôle UI n'est actif
  if (!isControlActive) {
    orbitControl();
  }

  // Réinitialiser les rayons si le nombre ou l'écartement a changé
  if (rays.length !== sliders.count.value()) {
    initRays();
  } else {
    // Mettre à jour l'écartement en temps réel
    var gap = sliders.spacing.value();
    var count = rays.length;
    for (let i = 0; i < count; i++) {
      var angle = map(i, 0, count, 0, TWO_PI);
      rays[i].y = sin(angle) * gap;
      rays[i].z = cos(angle) * gap;
    }
  }

  let rot = sliders.rot.value();
  let rad = sliders.radius.value();
  let type = floor(sliders.type.value());
  let opac = sliders.alpha.value();
  let trailMax = sliders.trail.value();

  ambientLight(200);

  // IMPORTANT: Dessiner d'abord les lignes de référence (arrière-plan)
  noFill();
  stroke(255, 35);
  for (let r of rays) {
    beginShape();
    for (let xPos = -600; xPos <= 600; xPos += 40) {
      let p = getProjectedPos(xPos, r.y, r.z, rot, rad, type);
      vertex(p.x, p.y, p.z);
    }
    endShape();
  }

  // Animer les particules AVANT l'objet pour qu'elles soient en arrière-plan
  for (let r of rays) {
    r.progress = (r.progress + sliders.speed.value()) % 1.0;
    let rawX = lerp(-600, 600, r.progress);

    let pos = getProjectedPos(rawX, r.y, r.z, rot, rad, type);
    checkImpact(r, rawX, rad, type);

    if (trailMax <= 1) {
      r.history = [];
    } else {
      r.history.push(pos);
      if (r.history.length > trailMax) {
        r.history.shift();
      }
    }

    // Dessiner le train de billes jaunes (remplace les traînées)
    if (r.history.length > 1) {
      for (let i = 0; i < r.history.length; i++) {
        var p = r.history[i];
        // Opacité augmente avec la position dans le train (plus récent = plus opaque)
        let alpha = map(i, 0, r.history.length - 1, 50, 255);
        // Taille diminue légèrement vers l'arrière
        let size = map(i, 0, r.history.length - 1, 3, 5);

        push();
        translate(p.x, p.y, p.z);
        noStroke();
        fill(255, 255, 0, alpha); // Jaune avec opacité progressive
        sphere(size);
        pop();
      }
    }

    // Dessiner la particule principale (tête du train)
    push(); 
    translate(pos.x, pos.y, pos.z);
    noStroke(); 
    fill(255, 255, 0, 255); // Jaune pleine opacité
    sphere(5);
    pop();
  }

  // Dessiner l'objet central APRÈS les particules
  // Avec transparence, il laissera voir les particules
  push();
  rotateY(radians(rot));
  if (opac === 0) {
    // Si opacité = 0, ne rien dessiner
    noStroke(); 
    noFill();
  } else {
    noStroke();
    fill(0, 150, 255, opac); 
    shininess(20);
    specularMaterial(100, 150, 255);
  }
  if (type === 0) {
    // Cylindre : hauteur proportionnelle au rayon
    cylinder(rad, rad * 4, 32, 1);
  } else if (type === 1) {
    // Cube homothétique
    box(rad * 2, rad * 2, rad * 2);
  } else {
    sphere(rad, 32, 32);
  }
  pop();
}

function checkImpact(r, x, rad, type) {
  let limitX = rad;

  // Pour le cube
  if (type === 1) {
    // Vérifier si y et z sont dans les limites du cube
    if (abs(r.y) <= rad && abs(r.z) <= rad) {
      limitX = rad;
    } else {
      limitX = 0; // Hors du cube
    }
  }
  // Pour la sphère
  else if (type === 2) { 
    let dSq = rad * rad - (r.y * r.y + r.z * r.z);
    limitX = dSq > 0 ? sqrt(dSq) : 0;
  }
  // Pour le cylindre, limitX = rad (déjà défini)

  let currentlyInside = abs(x) < limitX;

  // Jouer le son uniquement si changement d'état ET cooldown respecté
  if (currentlyInside !== r.isInside) {
    let now = millis();
    if (checkboxSound.checked() && audioCtx && (now - lastSoundTime) > soundCooldown) {
      playNativeSound(currentlyInside ? 800 : 400);
      lastSoundTime = now;
    }
    r.isInside = currentlyInside;
  }
}

function playNativeSound(freq) {
  if (!audioCtx || audioCtx.state !== 'running') return;
  let o = audioCtx.createOscillator();
  var g = audioCtx.createGain();
  o.type = "sine";
  o.frequency.setValueAtTime(freq, audioCtx.currentTime);
  let v = sliders.vol.value();
  g.gain.setValueAtTime(v, audioCtx.currentTime);
  g.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + 0.1);
  o.connect(g);
  g.connect(audioCtx.destination);
  o.start();
  o.stop(audioCtx.currentTime + 0.1);
}

function getProjectedPos(x, y, z, rot, rad, type) {
  var limitX = rad; 

  // Pour le cube homothétique
  if (type === 1) {
    // Le cube a une taille de rad*2 dans toutes les directions
    if (abs(y) <= rad && abs(z) <= rad) {
      limitX = rad; // Dans le cube
    } else {
      limitX = 0; // Hors du cube
    }
  }
  // Pour la sphère
  else if (type === 2) { 
    var dSq = rad * rad - (y * y + z * z);
    limitX = dSq > 0 ? sqrt(dSq) : 0;
  }
  // Pour le cylindre homothétique (hauteur = rad*4)
  else if (type === 0) {
    // Vérifier si y est dans les limites du cylindre
    if (abs(y) <= rad * 2) {
      limitX = rad;
    } else {
      limitX = 0; // Hors du cylindre
    }
  }

  let ang = radians(rot) * 0.4;

  // Si la particule est à l'intérieur de la forme
  if (abs(x) < limitX) {
    return { 
      x: x * cos(ang) - z * sin(ang), 
      y: y, 
      z: x * sin(ang) + z * cos(ang) 
    };
  }

  // Si la particule est après la forme (sortie)
  if (x >= limitX) {
    let xOut = limitX * cos(ang) - z * sin(ang);
    let zOut = limitX * sin(ang) + z * cos(ang);
    return { 
      x: (x - limitX) + xOut, 
      y: y, 
      z: zOut 
    };
  }

  // Si la particule est avant la forme (pas encore entrée)
  if (x <= -limitX) {
    var xOut = -limitX * cos(ang) - z * sin(ang);
    var zOut = -limitX * sin(ang) + z * cos(ang);
    return { 
      x: (x + limitX) + xOut, 
      y: y, 
      z: zOut 
    };
  }

  return { x: x, y: y, z: z };
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

